mapper.select:
SELECT s.id, s.user_id, CONCAT(LEFT(u.phone_number, 3), '****', RIGHT(u.phone_number, 4)) AS masked_phone, s.game_key, c.title AS game_title, s.schema_ver, s.state_json, s.updated_at FROM game_user_save s LEFT JOIN users u ON u.user_id = s.user_id LEFT JOIN game_config c ON c.game_key = s.game_key
AND s.game_key = #{gameKey}
AND s.user_id = #{userId}
ORDER BY s.updated_at DESC
